// Génération du code court
function generateShortCode(longUrl, counter) {
  // Option A : hash de l'URL (MD5/SHA) tronqué -> collisions possibles
  // Option B : compteur global encodé en base62 -> unique, mais SPOF potentiel
  // Option C : plage d'IDs pré-allouée par serveur -> pas de SPOF, unique
  return encodeBase62(counter)
}

// Lecture : le chemin le plus emprunté
app.get('/:code', async (req, res) => {
  const longUrl = await cache.get(req.params.code)      // 1. cache d'abord
  if (longUrl) return res.redirect(longUrl)

  const fromDb = await db.findByCode(req.params.code)     // 2. sinon, base
  await cache.set(req.params.code, fromDb.longUrl)        // 3. on remplit le cache
  res.redirect(fromDb.longUrl)
})

// Fan-out on write : coûteux pour les comptes à millions de followers
function onNewPost(post) {
  const followers = getFollowers(post.authorId)  // peut être énorme
  for (const followerId of followers) {
    pushToFeedCache(followerId, post)             // écriture multipliée par N
  }
}

// Fan-out on read : simple à écrire, plus lent à lire
function getFeed(userId) {
  const following = getFollowing(userId)
  const recentPosts = getRecentPostsFrom(following) // agrégation à la volée
  return sortByTime(recentPosts)
}

// Approche hybride courante en production
function onNewPost(post) {
  if (getFollowerCount(post.authorId) < CELEBRITY_THRESHOLD) {
    fanOutOnWrite(post)      // comptes normaux : push immédiat
  }
  // comptes "célébrités" : fan-out on read au moment de la lecture
}

// Sharding : répartir les utilisateurs entre plusieurs bases
function getShardForUser(userId, shardCount) {
  return hash(userId) % shardCount   // même utilisateur -> toujours le même shard
}

// Conséquence : une requête simple reste rapide
const shard = getShardForUser(userId, 8)
db[shard].findUser(userId)             // 1 seule base interrogée

// Mais une requête cross-utilisateurs devient coûteuse
function getTopUsersGlobally() {
  const results = []
  for (const shard of allShards) {
    results.push(...shard.query('ORDER BY score DESC LIMIT 10'))
  }
  return mergeAndSort(results)          // agrégation manuelle entre shards
}

// Token bucket : implémentation simplifiée
class TokenBucket {
  constructor(capacity, refillRatePerSec) {
    this.capacity = capacity
    this.tokens = capacity
    this.refillRate = refillRatePerSec
    this.lastRefill = Date.now()
  }

  allow() {
    this.refill()
    if (this.tokens >= 1) {
      this.tokens -= 1
      return true          // requête acceptée
    }
    return false            // 429 Too Many Requests
  }

  refill() {
    const now = Date.now()
    const elapsedSec = (now - this.lastRefill) / 1000
    this.tokens = Math.min(this.capacity, this.tokens + elapsedSec * this.refillRate)
    this.lastRefill = now
  }
}

// Assignation d'une clé à un serveur sur l'anneau
function getServerForKey(key, servers) {
  const keyPos = hash(key) % RING_SIZE
  const sorted = [...servers].sort((a, b) => a.pos - b.pos)

  // premier serveur dont la position est >= à celle de la clé
  const target = sorted.find((s) => s.pos >= keyPos)

  return target || sorted[0]   // retour au début de l'anneau si aucun trouvé
}

// Nœuds virtuels : chaque serveur physique occupe PLUSIEURS positions
function addServerWithVirtualNodes(server, virtualCount, ring) {
  for (let i = 0; i < virtualCount; i++) {
    ring.push({ id: server.id, pos: hash(server.id + '-' + i) % RING_SIZE })
  }
}
